 2	ghost function power(n: real, alpha: real): real
 3	    requires n > 0.0 && alpha > 0.0
 4	    ensures power(n, alpha) > 0.0
 5	
 6	ghost function log(n: real, alpha: real): real
 7	    requires n > 0.0 && alpha > 0.0
 8	    ensures log(n, alpha) > 0.0
 9	
10	lemma consistency(n: real, alpha: real)
11	    requires n > 0.0 && alpha > 0.0
12	    ensures log(power(n,alpha), alpha) == n
13	    ensures power(log(n, alpha), alpha) == n
14	
15	lemma logarithmSum(n: real, alpha: real, x: real, y: real)
16	    requires n > 0.0 && alpha > 0.0
17	    requires x > 0.0
18	    requires n == x * y
19	    ensures log(n,alpha) == log(x, alpha) +  log(y, alpha)
20	
21	lemma powerLemma(n: real, alpha: real)
22	    requires n > 0.0
23	    ensures power(n, alpha) * alpha == power(n+1.0, alpha)
24	
25	lemma power1(alpha: real)
26	    requires alpha > 0.0
27	    ensures power(1.0, alpha) == alpha
28	
29	lemma test() {
30	    var pow3 := power(3.0,4.0);
31	    consistency(3.0,4.0);
32	    assert log(pow3, 4.0) == 3.0;
33	    var log6 := log(6.0,8.0);
34	    logarithmSum(6.0, 8.0, 2.0, 3.0);
35	    assert log6 == log(2.0,8.0)+log(3.0,8.0);
36	}
37	
38	lemma test2() {
39	    var pow3 := power(3.0, 4.0);
40	    var power4 := power(4.0, 4.0);
41	    powerLemma(3.0, 4.0);
42	    assert pow3 * 4.0 == power4;
43	}
44	
45	method pow(n: nat, alpha: real) returns (product: real)
46	    requires n > 0
47	    requires alpha > 0.0
48	    ensures product == power(n as real, alpha)
49	{
50	    product := alpha;
51	    var i: nat := 1;
52	    power1(alpha);
53	    assert product == power(1.0, alpha);
54	    while i < n
55	        invariant i <= n
56	        invariant product == power(i as real, alpha)
57	    {
58	        powerLemma(i as real, alpha);
59	        product := product * alpha;
60	        i := i + 1;
61	    }
62	    assert i == n;
63	    assert product == power(n as real, alpha);
64	}

